import { View, Text, Pressable, Modal, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

function App() {
  const [open, setOpen] = useState(false);
  return (
    <View style={styles.s}>
      <Pressable nativeID="open" style={styles.b} onPress={() => setOpen(true)}><Text style={styles.t}>Сонголт</Text></Pressable>
      <Modal visible={open} transparent>
        {/* энд бичнэ үү: доод талд наасан хуудас (justifyContent: flex-end) */}
        <View nativeID="backdrop" style={styles.backdrop}>
          <View nativeID="sheet" style={styles.sheet}>
            <Text style={styles.h}>Хэмжээ сонгох</Text>
            <Pressable nativeID="pick" style={styles.opt} onPress={() => setOpen(false)}><Text>M хэмжээ</Text></Pressable>
          </View>
        </View>
      </Modal>
    </View>
  );
}

const styles = StyleSheet.create({
  s: { flex: 1, alignItems: "center", justifyContent: "center" },
  b: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12 }, t: { color: "#fff", fontWeight: "bold" },
  backdrop: { flex: 1 },
  sheet: { backgroundColor: "#fff", padding: 24, borderTopLeftRadius: 24, borderTopRightRadius: 24, gap: 12 },
  h: { fontSize: 18, fontWeight: "bold" }, opt: { padding: 14, backgroundColor: "#f1f5f9", borderRadius: 10 },
});

registerRootComponent(App);

